     1	import React, { useId } from "react";
     2	import {
     3	  Icon,
     4	  type IconName,
     5	  Label,
     6	  Position,
     7	  Tooltip,
     8	} from "@blueprintjs/core";
     9	import Description from "~/components/settings/SettingsDescription";
    10	import { settingAnchor } from "~/components/settings/utils/settingAnchor";
    11	import { describedSetting } from "~/components/settings/utils/settingsCatalog";
    12	import { withDocsLink } from "~/components/settings/utils/docs";
    13	
    14	/** Per-node settings are `global`: they live on the node type's page, so the whole graph sees them. */
    15	export type SettingScope = "personal" | "global";
    16	
    17	const SCOPE_INDICATORS = {
    18	  personal: {
    19	    icon: "person",
    20	    tooltip: "Personal, applies only to you",
    21	  },
    22	  global: {
    23	    icon: "globe",
    24	    tooltip: "Graph-wide, applies to everyone in this graph",
    25	  },
    26	} as const satisfies Record<SettingScope, { icon: IconName; tooltip: string }>;
    27	
    28	/** Raw <label> plus flex on purpose: Blueprint's `.bp3-label .bp3-popover-wrapper` and
    29	 *  `.bp3-icon` vertical-align rules would otherwise push the badge out of line. */
    30	const SettingScopeIndicator = ({ scope }: { scope: SettingScope }) => {
    31	  const { icon, tooltip } = SCOPE_INDICATORS[scope];
    32	  return (
    33	    <Tooltip content={tooltip} position={Position.TOP} hoverOpenDelay={300}>
    34	      <span
    35	        aria-label={tooltip}
    36	        className="dg-setting-row__scope flex h-5 w-5 flex-shrink-0 cursor-default items-center justify-center rounded opacity-60"
    37	      >
    38	        <Icon icon={icon} iconSize={12} />
    39	      </span>
    40	    </Tooltip>
    41	  );
    42	};
    43	
    44	type SettingItemRowProps = {
    45	  label: React.ReactNode;
    46	  description?: React.ReactNode;
    47	  /** A function receives the row's id to bind label and control; a node labels itself. */
    48	  control: React.ReactNode | ((controlId: string) => React.ReactNode);
    49	  scope?: SettingScope;
    50	  /** `below` is for controls too tall to sit beside the label, such as a textarea. */
    51	  controlPlacement?: "trailing" | "below";
    52	  settingKeys?: string[];
    53	  error?: string;
    54	  /** Pre-overhaul label, description and control stack, kept for the Export dialog's options. */
    55	  inline?: boolean;
    56	};
    57	
    58	const SettingItemRow = ({
    59	  label,
    60	  description,
    61	  control,
    62	  scope,
    63	  controlPlacement = "trailing",
    64	  settingKeys,
    65	  error,
    66	  inline = false,
    67	}: SettingItemRowProps): React.ReactElement => {
    68	  const controlId = useId();
    69	  const isAssociated = typeof control === "function";
    70	  // Falls back to the catalog so the row and search read one description.
    71	  const authored =
    72	    description === undefined ? describedSetting(settingKeys) : undefined;
    73	  const resolvedDescription =
    74	    description ??
    75	    (authored
    76	      ? authored.docsLink
    77	        ? withDocsLink(authored.description, authored.docsLink)
    78	        : authored.description
    79	      : undefined);
    80	  if (inline) {
    81	    return (
    82	      <Label {...(settingKeys ? settingAnchor(settingKeys) : {})}>
    83	        {label}
    84	        {resolvedDescription ? (
    85	          <Description description={resolvedDescription} />
    86	        ) : null}
    87	        {error ? (
    88	          <div className="text-sm font-medium text-red-700">{error}</div>
    89	        ) : null}
    90	        {isAssociated ? control(controlId) : control}
    91	      </Label>
    92	    );
    93	  }
    94	  // Description is a sibling of the label: nested, its doc links would toggle the control (ENG-2080).
    95	  const LabelTag = isAssociated ? "label" : "div";
    96	
    97	  return (
    98	    <div
    99	      {...(settingKeys ? settingAnchor(settingKeys) : {})}
   100	      className={`dg-setting-row py-3 ${
   101	        controlPlacement === "trailing"
   102	          ? "flex items-center justify-between gap-4"
   103	          : "flex flex-col gap-2"
   104	      }`}
   105	    >
   106	      <div className="flex min-w-0 flex-col gap-0.5">
   107	        <LabelTag
   108	          {...(isAssociated ? { htmlFor: controlId } : {})}
   109	          className={`mb-0 flex items-center gap-2 font-semibold ${
   110	            isAssociated ? "cursor-pointer" : ""
   111	          }`}
   112	        >
   113	          {scope ? <SettingScopeIndicator scope={scope} /> : null}
   114	          <span>{label}</span>
   115	        </LabelTag>
   116	        {resolvedDescription ? (
   117	          <div className="text-sm font-normal text-gray-500">
   118	            {resolvedDescription}
   119	          </div>
   120	        ) : null}
   121	        {error ? (
   122	          <div className="text-sm font-medium text-red-700">{error}</div>
   123	        ) : null}
   124	      </div>
   125	      <div
   126	        className={controlPlacement === "trailing" ? "flex-shrink-0" : "w-full"}
   127	      >
   128	        {isAssociated ? control(controlId) : control}
   129	      </div>
   130	    </div>
   131	  );
   132	};
   133	
   134	export default SettingItemRow;
