export default {
  async run({ page, outDir }) {
    const dialog = page.locator(".dg-settings-tabs").first();
    await dialog.waitFor({ timeout: 20000 });
    const info = await page.evaluate(() => {
      const list = document.querySelector(".dg-settings-tabs .bp3-tab-list");
      const input = list.querySelector("input[placeholder='Search settings']");
      const header = [...list.children].find((c) => c.textContent.trim() === "Preferences");
      const r = (el) => { const b = el.getBoundingClientRect(); return { top: Math.round(b.top), bottom: Math.round(b.bottom), h: Math.round(b.height) }; };
      const chain = [];
      for (let el = input; el && el !== list; el = el.parentElement) {
        const cs = getComputedStyle(el);
        chain.push({ tag: el.tagName, cls: el.className, ...r(el), display: cs.display, position: cs.position, height: cs.height, flex: cs.flex, minH: cs.minHeight, overflow: cs.overflow });
      }
      const ls = getComputedStyle(list);
      const stamp = [...document.querySelectorAll(".bp3-dialog span")].map((s) => s.textContent).find((t) => /^v\d/.test(t));
      return { stamp, header: r(header), list: { ...r(list), display: ls.display, flexDir: ls.flexDirection, maxH: ls.maxHeight, overflowY: ls.overflowY }, chain, listChildren: [...list.children].slice(0, 4).map((c) => ({ cls: c.className, ...r(c) })) };
    });
    await page.locator(".dg-settings-tabs .bp3-tab-list").first().screenshot({ path: `${outDir}/eng2451-sidebar.png` });
    return info;
  },
};
